// Generates lib/mock/messages.ts from contracts/messages.yaml (the contract is the source of truth).
// Run: npm run sync:messages. `npm test` fails when the generated file drifts from the contract.
import { readFileSync, writeFileSync } from "node:fs";
import { parse } from "yaml";

const CONTRACT = new URL("../../../contracts/messages.yaml", import.meta.url);
const OUT = new URL("../lib/mock/messages.ts", import.meta.url);

// The leaves the scripted agent and the pages use. Add a path here when a page needs another text.
export const PATHS = [
  "greet.hello", "greet.capability_1", "greet.capability_2", "greet.capability_3", "greet.human_review",
  "plan.intro", "plan.step_open_case", "plan.step_open_case_no_merchant", "plan.step_block_card", "plan.step_verify",
  "plan.step_deadline", "plan.step_person", "plan.confirm_ask",
  "connect.requested", "connect.requested_no_window",
  "status.label.received", "status.label.in_review", "status.label.resolved", "status.label.closed",
  "status.credit_deadline", "status.deadline_unknown",
  "suggest.report_unrecognized", "suggest.talk_to_person", "suggest.confirm_yes", "suggest.confirm_no",
  "suggest.add_info", "suggest.request_call", "suggest.view_case",
  "receipt.title", "receipt.card_blocked", "receipt.what_ai_did_blocked", "receipt.what_ai_did_case_only",
  "receipt.what_a_person_does", "receipt.case_link",
  "receipt.credit_deadline", "receipt.ruling_deadline", "receipt.deadline_unknown",
];

const yaml = parse(readFileSync(CONTRACT, "utf8"));
const tree = {};
for (const path of PATHS) {
  const parts = path.split(".");
  const leaf = parts.reduce((node, key) => node[key], yaml);
  let target = tree;
  for (const key of parts.slice(0, -1)) target = target[key] ??= {};
  target[parts.at(-1)] = { es: leaf.es, pt: leaf.pt };
}

const text = `// Customer-facing ES/PT texts for the mock agent, copied from contracts/messages.yaml (spec 04 §4.2, §4.5; spec 01 §6.7).
// GENERATED by scripts/sync-messages.mjs (npm run sync:messages): do not edit by hand. \`npm test\` fails if it drifts.
// Placeholders use ONE syntax, {name}, filled only with facts returned by tools (ADR 0016).
// Nothing here may mention the score, policy ids, zones or the transcript.
import type { Language } from "../types.ts";

export interface Message {
  es: string;
  pt: string;
}

export const MESSAGES = ${JSON.stringify(tree, null, 2)} as const;

/** Fills {name} placeholders. A missing fact throws: a template that needs a fact the tool did not return is not rendered. */
export function fill(message: Message, lang: Language, facts: Record<string, string | number> = {}): string {
  return message[lang].replace(/\\{([a-z_0-9]+)\\}/g, (_m, name: string) => {
    const value = facts[name];
    if (value === undefined) throw new Error(\`missing fact "\${name}" for a customer message\`);
    return String(value);
  });
}
`;

if (process.argv.includes("--check")) {
  const current = readFileSync(OUT, "utf8");
  if (current !== text) {
    console.error("lib/mock/messages.ts is out of date with contracts/messages.yaml: run `npm run sync:messages`");
    process.exit(1);
  }
} else {
  writeFileSync(OUT, text);
}
